            if model_id:
                current = self.config.per_model_directives.get(model_id, "")
                directive = "[IMMUNE] Verify your own findings with SymPy or dimensional analysis before reporting."
                new_directive = (current + " " + directive).strip()
                if len(new_directive) <= self.config.max_per_model_directive_chars:
                    self.config.per_model_directives[model_id] = new_directive
                return {"parameter": "per_model_directives", "old": "", "new": "verification directive added",
                        "reason": diagnosis.pathology}
        elif transform_name == "lower_feasibility_threshold":
            # This parameter is not in the config interface summary; likely a bug.
            # For now, log an advisory adjustment.
            return {"parameter": "feasibility_threshold", "old": "unknown", "new": "lowered",
                    "reason": diagnosis.pathology, "advisory": True}
        elif transform_name == "flag_verification_unreliable":
            # This parameter is not in the config interface summary; likely a bug.
